// Module 7's approach: in-memory storage (NOT a real database)
let tasks = [{ id: 1, title: 'Buy groceries', completed: false }];

app.post('/tasks', (req, res) => {
  tasks.push({ id: Date.now(), title: req.body.title, completed: false });
  res.status(201).json({ success: true });
});
// PROBLEM 1: if the server restarts, tasks resets to its hardcoded
//            initial value - every task ever added is gone.
// PROBLEM 2: if two requests hit this route at the exact same instant,
//            there's no protection against subtle, hard-to-predict
//            interleaving issues as both modify the same array.
// PROBLEM 3: finding 'all tasks for user X, sorted by date, only the
//            first 20' would require writing manual filter/sort/slice
//            logic yourself, repeated for every different query shape.

// With a REAL database (conceptual - actual MongoDB/PostgreSQL syntax
// is introduced starting in lesson 3 of this module):
//
// app.post('/tasks', async (req, res, next) => {
//   try {
//     const newTask = await database.tasks.insertOne({
//       title: req.body.title,
//       completed: false
//     });
//     res.status(201).json({ success: true, data: newTask });
//   } catch (err) { next(err); }
// });
//
// This version persists tasks durably (surviving restarts), lets the
// database itself handle safe concurrent writes, and provides a real
// query language for exactly the kind of filtering/sorting/pagination
// PROBLEM 3 described, instead of hand-rolling it in application code.

// SQL/Relational approach (PostgreSQL, full syntax in lesson 9):
// A 'posts' table, a separate 'comments' table, related via a foreign key
//
// posts table:
// | id | title           | author_id |
// |  1 | 'Hello World'   |     7     |
//
// comments table:
// | id | post_id | text             |
// |  1 |    1     | 'Great post!'    |
// |  2 |    1     | 'Thanks for this'|
//
// Retrieving a post WITH its comments requires an explicit JOIN
// across both tables at query time (covered fully in lesson 9).

// NoSQL/Document approach (MongoDB, full syntax in lessons 3-4):
// A single 'posts' collection, with comments embedded directly
// inside each post document - no separate table or join needed
{
  _id: 1,
  title: 'Hello World',
  authorId: 7,
  comments: [
    { text: 'Great post!' },
    { text: 'Thanks for this' }
  ]
}
// Retrieving this post and ALL its comments together requires only
// a single lookup, since the comments already live inside the document.

