Create:
const result = await collection.insertOne({ title: 'New task', completed: false });
// result.insertedId is the new document's generated _id

Read (all matching documents):
const allTasks = await collection.find({ completed: false }).toArray();
// find() returns a cursor; .toArray() converts it into a usable array

Read (one specific document):
const task = await collection.findOne({ _id: new ObjectId(id) });
// returns the matching document directly, or null if none found

Update:
const result = await collection.updateOne(
  { _id: new ObjectId(id) },
  { $set: { completed: true } }
);
// result.matchedCount tells you whether a document was actually found and updated

Delete:
const result = await collection.deleteOne({ _id: new ObjectId(id) });
// result.deletedCount tells you whether a document was actually found and deleted

