import express from 'express';
import pg from 'pg';

const { Pool } = pg;
const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: 'postgresql://localhost:5432/todoApp'
});

function isValidString(value) {
  return typeof value === 'string' && value.trim() !== '';
}

// CREATE
app.post('/tasks', async (req, res, next) => {
  try {
    if (!isValidString(req.body.title)) {
      return res.status(400).json({ success: false, error: 'A non-empty title is required' });
    }

    const result = await pool.query(
      'INSERT INTO tasks (title, completed) VALUES ($1, $2) RETURNING *',
      [req.body.title.trim(), false]
    );
    res.status(201).json({ success: true, data: result.rows[0] });
  } catch (err) {
    next(err);
  }
});

// READ (list)
app.get('/tasks', async (req, res, next) => {
  try {
    const result = await pool.query('SELECT * FROM tasks ORDER BY id');
    res.json({ success: true, data: result.rows });
  } catch (err) {
    next(err);
  }
});

// UPDATE
app.patch('/tasks/:id', async (req, res, next) => {
  try {
    const result = await pool.query(
      'UPDATE tasks SET completed = $1 WHERE id = $2 RETURNING *',
      [req.body.completed, req.params.id]
    );

    if (result.rows.length === 0) {
      return res.status(404).json({ success: false, error: 'Task not found' });
    }

    res.json({ success: true, data: result.rows[0] });
  } catch (err) {
    next(err);
  }
});

