app.delete('/tasks/:id', async (req, res, next) => {
  try {
    const result = await pool.query('DELETE FROM tasks WHERE id = $1', [req.params.id]);

    if (result.rowCount === 0) {
      return res.status(404).json({ success: false, error: 'Task not found' });
    }

    res.status(204).send();
  } catch (err) {
    next(err);
  }
});

