codingChallenge.solutionExample:
import pg from 'pg';
const { Pool } = pg;
const pool = new Pool({ connectionString: 'postgresql://localhost:5432/libraryApp' });

app.post('/books', async (req, res, next) => {
  try {
    const { title, author_id } = req.body;
    if (!title || !author_id) {
      return res.status(400).json({ success: false, error: 'title and author_id are required' });
    }

    const result = await pool.query(
      'INSERT INTO books (title, author_id) VALUES ($1, $2) RETURNING *',
      [title, author_id]
    );
    res.status(201).json({ success: true, data: result.rows[0] });
  } catch (err) {
    next(err);
  }
});

app.get('/authors/:id/books', async (req, res, next) => {
  try {
    const result = await pool.query(
      `SELECT authors.name, books.title
       FROM authors
       JOIN books ON books.author_id = authors.id
       WHERE authors.id = $1`,
      [req.params.id]
    );

    if (result.rows.length === 0) {
      return res.status(404).json({ success: false, error: 'No author or books found' });
    }

    res.json({ success: true, data: result.rows });
  } catch (err) {
    next(err);
