// STEP 1 - Paradigm fit: Personal finance tracker. Transactions and
// account balances require STRICT consistency (a transfer must correctly
// affect both accounts together, balances must never be ambiguous).
// DECISION: PostgreSQL - this is exactly the consistency-critical,
// well-defined-relationship scenario lesson 2 favors for relational data.

// STEP 2 - Modeling:
// Entities: Account, Transaction
// accounts table: id, name, balance
// transactions table: id, account_id (foreign key), amount, type, created_at

// STEP 3 - Validation/verification: validate amount is a positive number
// and type is one of ('deposit', 'withdrawal') before INSERT; after any
// UPDATE/DELETE, explicitly check result.rowCount before responding success

// STEP 4 - Query patterns: "all transactions for account X, sorted by date"
// (WHERE + ORDER BY); "account balance alongside its most recent 10
// transactions" (JOIN + LIMIT)

// IMPLEMENTATION:
import pg from 'pg';
const { Pool } = pg;
const pool = new Pool({ connectionString: 'postgresql://localhost:5432/financeApp' });

app.post('/transactions', async (req, res, next) => {
  try {
    const { account_id, amount, type } = req.body;
    if (typeof amount !== 'number' || amount <= 0 || !['deposit', 'withdrawal'].includes(type)) {
      return res.status(400).json({ success: false, error: 'Valid amount and type are required' });
    }

    const result = await pool.query(
      'INSERT INTO transactions (account_id, amount, type) VALUES ($1, $2, $3) RETURNING *',
      [account_id, amount, type]
    );
    res.status(201).json({ success: true, data: result.rows[0] });
  } catch (err) {
    next(err);
  }
});

app.get('/accounts/:id/transactions', async (req, res, next) => {
  try {
    const result = await pool.query(
      'SELECT * FROM transactions WHERE account_id = $1 ORDER BY created_at DESC',
      [req.params.id]
    );
    res.json({ success: true, data: result.rows });
  } catch (err) {
    next(err);
  }
});
